pages=0
while path:
    data=api(path)
    pages += 1
    for order in data['items']:
        oid=order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        dt=datetime.fromisoformat(order['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
        if order['status'] == 'shipped' and start <= dt < end:
            qualifying.append(order)
    path=data['next']

customers={}
by_region={k:0 for k in ('north','south','east','west')}
for order in qualifying:
    cid=order['customer_id']
    if cid not in customers:
        customers[cid]=api('/customers/'+str(cid))
    customer=customers[cid]
    discounted=(Decimal(order['amount_cents'])*(Decimal(100)-Decimal(customer['discount_pct']))/Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)

result={'total_cents':sum(by_region.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':by_region}
